def _assign_existing_rows_to_first_admin() -> None:
    """Installations from before workspaces existed: everything belongs to the first admin.

    Audit entries are deliberately left untouched: changing them would break the hash chain.
    """
    bind = op.get_bind()
    admin_id = bind.execute(sa.text("SELECT id FROM users WHERE role = 'admin' ORDER BY id LIMIT 1")).scalar()
    if admin_id is None:
        return
    for table in OWNED_TABLES:
        bind.execute(
            sa.text(f"UPDATE {table} SET owner_id = :owner WHERE owner_id IS NULL"),  # noqa: S608 - fixed table names
            {"owner": admin_id},
        )
    bind.execute(
        sa.text("UPDATE signing_keys SET owner_id = :owner WHERE purpose = 'baseline' AND owner_id IS NULL"),
        {"owner": admin_id},
    )


